/**
 * Returns the full catalog of all equipment sprite assets.
 * @returns {EquipmentAsset[]}
 */
export function getEquipmentAssets() {
    return EQUIPMENT_ASSETS;
}

/**
 * Returns equipment sprite assets filtered by game slot type.
 * @param {string} slotType — One of: "weapon", "helmet", "chest", "amulet", "crystal"
 * @returns {EquipmentAsset[]}
 */
export function getEquipmentAssetsBySlot(slotType) {
    return EQUIPMENT_ASSETS.filter(a => a.slot_type === slotType);
}

/**
 * Returns equipment sprite assets filtered by asset category folder.
 * @param {string} category — One of ASSET_CATEGORIES
 * @returns {EquipmentAsset[]}
 */
export function getEquipmentAssetsByCategory(category) {
    return EQUIPMENT_ASSETS.filter(a => a.category === category);
}
